package com.pillar; import com.fasterxml.jackson.databind.*; import javax.crypto.*; import javax.crypto.spec.*; import java.security.*; import java.nio.charset.StandardCharsets; import java.util.*;
public class Webhook { public static Map constructEvent(byte[] payload,String header,String secret,long toleranceSeconds){ try{ Map<String,String> parts=new HashMap<>(); for(String p:header.split(",")){var kv=p.split("=",2); if(kv.length==2)parts.put(kv[0],kv[1]);} long ts=Long.parseLong(parts.getOrDefault("t","0")); if(Math.abs(System.currentTimeMillis()/1000-ts)>toleranceSeconds) throw new IllegalArgumentException("stale"); Mac mac=Mac.getInstance("HmacSHA256"); mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256")); mac.update((ts+".").getBytes(StandardCharsets.UTF_8)); byte[] expected=mac.doFinal(payload); byte[] got=HexFormat.of().parseHex(parts.get("v1")); if(!MessageDigest.isEqual(expected,got)) throw new IllegalArgumentException("bad signature"); return new ObjectMapper().readValue(payload, Map.class);}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalArgumentException(e);} } }
